private boolean hasAnyUnveiled(int minX, int minY, int mapW, int mapH) {
    for (int my = 0; my < mapH; my++) {
        int y = minY + my;
        for (int mx = 0; mx < mapW; mx++) {
            int x = minX + mx;
            int packed = (y << 6) | x;
            if (((MainActivity.this.renderWords[packed + 16] >>> 24) & 1) != 0) {
                return SMOOTH_HUD_PURCHASE_SCROLL;
            }
        }
    }
    return false;
}

private boolean isPackedUnveiled(int packed) {
    if (MainActivity.this.cheatRevealMap) {
        if (MainActivity.this.renderWords == null || packed < 0 || packed >= 4096) {
            return false;
        }
        return SMOOTH_HUD_PURCHASE_SCROLL;
    }
    if (MainActivity.this.renderWords == null || packed < 0 || packed >= 4096 || ((MainActivity.this.renderWords[packed + 16] >>> 24) & 1) == 0) {
        return false;
    }
    return SMOOTH_HUD_PURCHASE_SCROLL;
}

private boolean isCombatEffectVisibleAtPacked(int packed) {
    int playerHouse;
    if (MainActivity.this.renderWords == null || packed < 0 || packed >= 4096) {
        return false;
    }
    if (isPackedUnveiled(packed) || (playerHouse = MainActivity.this.renderWords[5] & 255) >= 6) {
        return SMOOTH_HUD_PURCHASE_SCROLL;
    }
    int i = 0;
    while (i < 128) {
        int base = (i * 12) + MainActivity.STRUCT_OFFSET;
        int meta = MainActivity.this.renderWords[base];
        if ((Integer.MIN_VALUE & meta) != 0) {
            int visibilityWord = (MainActivity.this.structureRenderAux == null || i >= MainActivity.this.structureRenderAux.length) ? 0 : MainActivity.this.structureRenderAux[i];
            int seenMask = visibilityWord & 63;
            if (((1 << playerHouse) & seenMask) == 0) {
                continue;
            } else {
                int count = (meta >>> 16) & 255;
                for (int j = 0; j < count && j < 9; j++) {
                    if ((MainActivity.this.renderWords[base + 3 + j] & 65535) == packed) {
                        return SMOOTH_HUD_PURCHASE_SCROLL;
                    }
                }
            }
        }
        i++;
    }
    return false;
}

private boolean isUnitVisibleToPlayer(int meta, int base) {
    if (MainActivity.this.renderWords == null) {
        return false;
    }
    int playerHouse = MainActivity.this.renderWords[5] & 255;
    if (playerHouse >= 6 || MainActivity.this.cheatRevealMap) {
        return SMOOTH_HUD_PURCHASE_SCROLL;
    }
    int house = meta & 255;
    if (house == playerHouse) {
        return SMOOTH_HUD_PURCHASE_SCROLL;
    }
    long position = MainActivity.this.renderWords[base + 1] & 4294967295L;
    int rawX = (int) (position & 65535);
    int rawY = (int) (65535 & (position >>> 16));
    int packed = (((rawY >>> 8) & 63) << 6) | ((rawX >>> 8) & 63);
    return isPackedUnveiled(packed);
}

