private void focusGroupFavorite(FavoriteRef ref) {
    if (!MainActivity.this.twoFingerGroupSelectionEnabled || !favoriteRefIsLive(ref) || MainActivity.this.nativeHandle == 0) {
        return;
    }
    clearTwoFingerSelection();
    float wx = 0.0f;
    float wy = 0.0f;
    int n = 0;
    int last = -1;
    for (int i = 0; i < ref.groupRaws.length; i++) {
        int raw = ref.groupRaws[i];
        if (raw >= 0 && raw < 128) {
            int meta = MainActivity.this.renderWords[(raw * 4) + MainActivity.UNIT_OFFSET];
            if (twoFingerEligible(raw, meta) && (65535 & meta) == ref.groupIdentities[i] && ref.groupGenerations[i] == this.unitFavoriteGeneration[raw]) {
                this.multiSelection[raw] = SMOOTH_HUD_PURCHASE_SCROLL;
                this.multiSelectionIdentity[raw] = ref.groupIdentities[i];
                this.multiSelectionCount++;
                wx += unitRenderWorldX(raw, 0);
                wy += unitRenderWorldY(raw, 0);
                last = raw;
                n++;
            }
        }
    }
    if (n == 0) {
        return;
    }
    if (n == 1) {
        collapseGroupToSingleSelection();
    } else {
        MainActivity.nativeTacticalClearSelection(MainActivity.this.nativeHandle);
        refreshInteractionSnapshots();
        if (MainActivity.nativeGroupSelectionSound(MainActivity.this.nativeHandle, last, this.multiSelectionIdentity[last]) > 0) {
            MainActivity.this.consumeSoundEventSnapshot();
        }
    }
    if (favoriteCenterOnSelect(ref)) {
        beginFavoriteCameraMotion(wx / n, wy / n, null);
    }
    invalidate();
}

private FavoriteRef playerConstructionYardFavorite() {
    if (MainActivity.this.renderWords == null) {
        return null;
    }
    int player = MainActivity.this.renderWords[5] & 255;
    for (int raw = 0; raw < 128; raw++) {
        int meta = MainActivity.this.renderWords[(raw * 12) + MainActivity.STRUCT_OFFSET];
        if ((Integer.MIN_VALUE & meta) != 0 && (meta & 255) == player && ((meta >>> 8) & 255) == 8) {
            return makeFavoriteRef(2, raw);
        }
    }
    return null;
}

private boolean isFixedConstructionYardFavorite(FavoriteRef ref) {
    if (ref == null || ref.kind != 2 || ref.type != 8 || MainActivity.this.renderWords == null) {
        return false;
    }
    FavoriteRef yard = playerConstructionYardFavorite();
    return favoriteSameObject(ref, yard);
}

private int customFavoriteIndex(FavoriteRef ref) {
    for (int i = 0; i < this.customFavorites.size(); i++) {
        if (favoriteSameObject(this.customFavorites.get(i), ref)) {
            return i;
        }
    }
    return -1;
}

private int hiddenFavoriteIndex(FavoriteRef ref) {
    for (int i = 0; i < this.hiddenFavoriteButtons.size(); i++) {
        if (favoriteSameObject(this.hiddenFavoriteButtons.get(i), ref)) {
            return i;
        }
    }
    return -1;
}

private boolean favoriteButtonHidden(FavoriteRef ref) {
    if (hiddenFavoriteIndex(ref) >= 0) {
        return SMOOTH_HUD_PURCHASE_SCROLL;
    }
    return false;
}

private void setFavoriteButtonHidden(FavoriteRef ref, boolean hidden) {
    if (ref == null) {
        return;
    }
    int index = hiddenFavoriteIndex(ref);
    if (hidden) {
        if (index < 0) {
            this.hiddenFavoriteButtons.add(ref);
        }
    } else if (index >= 0) {
        this.hiddenFavoriteButtons.remove(index);
    }
}

private List<FavoriteRef> visibleFavorites() {
    updateFavoriteGenerationsAndPrune();
    List<FavoriteRef> result = new ArrayList<>();
    FavoriteRef yard = playerConstructionYardFavorite();
    if (yard != null && !favoriteButtonHidden(yard)) {
        result.add(yard);
    }
    for (FavoriteRef ref : this.customFavorites) {
        if (result.size() >= 6) {
            break;
        }
        if (ref.kind != 3 || MainActivity.this.twoFingerGroupSelectionEnabled) {
            if (favoriteRefIsLive(ref) && !favoriteSameObject(ref, yard) && !favoriteButtonHidden(ref)) {
                result.add(ref);
            }
        }
    }
    return result;
}

private boolean isFavoriteLiveUnitRaw(int raw) {
    if (MainActivity.this.renderWords == null || raw < 0 || raw >= 128) {
        return false;
    }
    int meta = MainActivity.this.renderWords[(raw * 4) + MainActivity.UNIT_OFFSET];
    if ((Integer.MIN_VALUE & meta) == 0) {
        return false;
    }
    int type = (meta >>> 8) & 255;
    int house = meta & 255;
    int generation = this.unitFavoriteGeneration[raw];
    for (FavoriteRef ref : this.customFavorites) {
        if (ref.kind == 1 && ref.raw == raw && ref.type == type && ref.house == house && ref.generation == generation && favoriteRefIsLive(ref)) {
            return SMOOTH_HUD_PURCHASE_SCROLL;
        }
    }
    return false;
}

private boolean isFavoriteLiveStructureRaw(int raw) {
    FavoriteRef yard;
    if (MainActivity.this.renderWords == null || raw < 0 || raw >= 128) {
        return false;
    }
    int meta = MainActivity.this.renderWords[(raw * 12) + MainActivity.STRUCT_OFFSET];
    if ((Integer.MIN_VALUE & meta) == 0) {
        return false;
    }
    int type = (meta >>> 8) & 255;
    int house = meta & 255;
    int generation = this.structureFavoriteGeneration[raw];
    int playerHouse = MainActivity.this.renderWords[5] & 255;
    if (type == 8 && house == playerHouse && (yard = playerConstructionYardFavorite()) != null && yard.raw == raw && yard.generation == generation) {
        return SMOOTH_HUD_PURCHASE_SCROLL;
    }
    for (FavoriteRef ref : this.customFavorites) {
        if (ref.kind == 2 && ref.raw == raw && ref.type == type && ref.house == house && ref.generation == generation && favoriteRefIsLive(ref)) {
            return SMOOTH_HUD_PURCHASE_SCROLL;
        }
    }
    return false;
}

